import os
from typing import Dict, Any
import boto3
from botocore.exceptions import ClientError

class DocumentExtractor:
    def __init__(self):
        self.client = boto3.client(
            'textract',
            aws_access_key_id=os.getenv('AWS_ACCESS_KEY_ID'),
            aws_secret_access_key=os.getenv('AWS_SECRET_ACCESS_KEY'),
            region_name=os.getenv('AWS_REGION', 'us-east-1')
        )

    def extract_and_validate_document(
        self,
        document_bytes: bytes,
        required_fields: Dict[str, float]
    ) -> Dict[str, Any]:
        """
        Extracts structured data from a document using Amazon Textract,
        validates required fields, and checks confidence scores.

        Args:
            document_bytes: The document file in bytes (PDF, PNG, or JPEG).
            required_fields: Dictionary of field names and their minimum confidence scores.

        Returns:
            Dictionary containing extracted fields, confidence scores, and validation results.
        """
        try:
            response = self.client.analyze_document(
                Document={'Bytes': document_bytes},
                FeatureTypes=['FORMS']
            )

            extracted_data = {}
            validation_results = {}

            # Extract key-value pairs from the document
            for item in response.get('Blocks', []):
                if item['BlockType'] == 'KEY_VALUE_SET' and 'KEY' in item['EntityTypes']:
                    key = None
                    value = None
                    for relationship in item.get('Relationships', []):
                        if relationship['Type'] == 'VALUE':
                            for value_id in relationship['Ids']:
                                value_block = next(
                                    (b for b in response['Blocks'] if b['Id'] == value_id),
                                    None
                                )
                                if value_block and value_block['BlockType'] == 'WORD':
                                    value = value_block.get('Text', '')
                        elif relationship['Type'] == 'CHILD':
                            for child_id in relationship['Ids']:
                                child_block = next(
                                    (b for b in response['Blocks'] if b['Id'] == child_id),
                                    None
                                )
                                if child_block and child_block['BlockType'] == 'WORD':
                                    key = child_block.get('Text', '')

                    if key and value:
                        confidence = item.get('Confidence', 0.0)
                        extracted_data[key] = {
                            'value': value,
                            'confidence': confidence
                        }

            # Validate required fields and confidence scores
            for field, min_confidence in required_fields.items():
                if field in extracted_data:
                    field_data = extracted_data[field]
                    validation_results[field] = {
                        'present': True,
                        'confidence': field_data['confidence'],
                        'valid': field_data['confidence'] >= min_confidence,
                        'value': field_data['value']
                    }
                else:
                    validation_results[field] = {
                        'present': False,
                        'confidence': 0.0,
                        'valid': False,
                        'value': None
                    }

            return {
                'extracted_data': extracted_data,
                'validation_results': validation_results,
                'document_status': 'processed'
            }

        except ClientError as e:
            return {
                'error': str(e),
                'document_status': 'failed'
            }
